    const input = fs.readFileSync(0, 'utf-8');
    let pos = 0;

    function nextInt() {
        while (pos < input.length && input.charCodeAt(pos) <= 32) {
            pos++;
        }
        if (pos >= input.length) return null;
        let res = 0;
        while (pos < input.length && input.charCodeAt(pos) > 32) {
            res = res * 10 + (input.charCodeAt(pos) - 48);
            pos++;
        }
        return res;
    }

    const n = nextInt();
    if (n === null) return;

    // opposite index mapping:
    // A (0) <-> F (5)
    // B (1) <-> D (3)
    // C (2) <-> E (4)
    const opp = [5, 3, 4, 1, 2, 0];

    const dice = [];
    for (let i = 0; i < n; i++) {
        const d = [];
        for (let j = 0; j < 6; j++) {
            d.push(nextInt());
        }
        dice.push(d);
    }

    let maxSum = 0;

    // Test each of the 6 possible bottom faces for the first die
    for (let initialBottomIdx = 0; initialBottomIdx < 6; initialBottomIdx++) {
        let currentSum = 0;
        let topVal = dice[0][opp[initialBottomIdx]];
        let bottomVal = dice[0][initialBottomIdx];

        // Max lateral for the first die
        let maxSide = 0;
        for (let val = 6; val >= 1; val--) {
            if (val !== bottomVal && val !== topVal) {
                maxSide = val;
                break;
            }
        }
        currentSum += maxSide;

        // Propagate up the tower
        for (let i = 1; i < n; i++) {
            const d = dice[i];
            const bVal = topVal;
            // Find index of bVal in this die
            let bIdx = -1;
            for (let j = 0; j < 6; j++) {
                if (d[j] === bVal) {
                    bIdx = j;
                    break;
                }
            }
            const tVal = d[opp[bIdx]];
            topVal = tVal;

            for (let val = 6; val >= 1; val--) {
                if (val !== bVal && val !== tVal) {
                    currentSum += val;
                    break;
                }
            }
        }

        if (currentSum > maxSum) {
            maxSum = currentSum;
        }
    }

    console.log(maxSum);
}

solve();
